@startuml

enum Unit {
  CELSIUS
  WATT
}

class SensorController {
}

class Apartment {
  + Address : string
  + EmailAddress : string
}

class Inhabitant {
  + Username : string
  + Password : string
  + IsAdministrator : boolean
}

class Room {
  + Description : string
}

class Sensor {
  + VendorId : string
  + Description : string
  + Unit : Unit
  + Threshold : float
}

class TemperatureSensor extends Sensor {
  + MinValue : float
  + MaxValue : float
}

class PowerSensor extends Sensor {
  + CounterReading : float
}

class MeasuredValue {
  + Timestamp : datetime
  + Value : float
}

class EMonitor {
}

SensorController "1" -- "1" Apartment : manages
Apartment "1" -- "1..*" Inhabitant : has
Apartment "1" -- "1..*" Room : consists of
Room "1" -- "1..*" Sensor : contains
Sensor "1" -- "0..*" MeasuredValue : records
SensorController "1" -- "0..*" Sensor : manages
SensorController "1" -- "0..*" MeasuredValue : stores
EMonitor ..> Sensor : checks thresholds
EMonitor ..> SensorController : sends alert messages

@enduml

